// Mesclado das partes traduzidas de parse_c (as partes quebram funções grandes no meio).
#![allow(unused_imports, ambiguous_glob_reexports)]
use crate::prelude::*;

// ---- part_000.rs ----

// Trecho 0 de parse.c (gerado pelo lemon a partir de parse.y): as diretivas %include (funções
// auxiliares das ações da gramática), as definições de tipo dos símbolos e a união YYMINORTYPE.
//
// Fora do porte:
//   - as macros `YYNOERRORRECOVERY`, `YYPARSEFREENEVERNULL`, `YYMALLOCARGTYPE`, `yytestcase` e
//     `sqlite3Parser_ENGINEALWAYSONSTACK`: são só chaves de compilação do motor do lemon, sem
//     código próprio no Rust;
//   - `updateDeleteLimitError()`: só existe sob `!SQLITE_ENABLE_UPDATE_DELETE_LIMIT &&
//     SQLITE_UDL_CAPABLE_PARSER`, e `SQLITE_UDL_CAPABLE_PARSER` nunca é definido no amalgamation
//     do 3.46.1 (a única ocorrência é esta própria condição), logo a função não entra no build;
//   - as definições `TK_*` (bloco `#ifndef TK_SEMI`): já vêm de `parse_h`, que é o parse.h que o
//     amalgamation inclui antes deste ponto.

/// Descreve o evento de um TRIGGER. `a` é o tipo do evento, um de TK_UPDATE, TK_INSERT, TK_DELETE
/// ou TK_INSTEAD. Se o evento tem a forma `UPDATE ON (a,b,c)`, a IdList `b` guarda a lista
/// "a,b,c".
#[derive(Clone, Default)]
pub struct TrigEvent {
    pub a: i32,
    pub b: Option<Box<IdList>>,
}

/// Limite de um quadro de janela: tipo do limite e a expressão associada.
#[derive(Clone, Default)]
pub struct FrameBound {
    pub e_type: i32,
    pub p_expr: Option<Box<Expr>>,
}

/// Desabilita a alocação lookaside para objetos que podem ser compartilhados entre conexões de
/// banco de dados.
pub fn disable_lookaside(p_parse: &mut Parse) {
    let db = p_parse.db.upgrade().expect("conexão de banco viva durante o parse");
    p_parse.disable_lookaside = p_parse.disable_lookaside.wrapping_add(1);
    // Macro DisableLookaside do C: o `disable_lookaside` do módulo de cabeçalho, chamado pelo
    // caminho completo para não recair nesta própria função.
    crate::prelude::disable_lookaside(&mut db.borrow_mut());
}

/// Num SELECT composto, garante que `p->pPrior->pNext==p` para todos os elementos da lista e que
/// o comprimento da lista não passa de SQLITE_LIMIT_COMPOUND_SELECT.
///
/// NOTA para o lead: no C, `pLoop->pNext = pNext` é um ponteiro de volta para o elemento da
/// direita. No modelo Rust `Select.p_prior` e `Select.p_next` são ambos `Option<Box<Select>>`
/// (donos), então o elo de volta não pode ser materializado sem ciclo de posse. Aqui o percurso
/// reproduz todos os demais efeitos (SF_COMPOUND em cada elemento visitado, contagem, mensagens
/// de erro); quem precisar do elo de volta deve percorrer a lista a partir de `p_prior`.
pub fn parser_double_link_select(p_parse: &mut Parse, p: &mut Select) {
    if p.p_prior.is_some() {
        let mut cnt: i32 = 1;
        let mut p_loop: &mut Select = &mut *p;
        loop {
            // pLoop->pNext = pNext (ver a nota acima)
            p_loop.sel_flags |= SF_COMPOUND;
            // pNext = pLoop; só o `op` do elemento da direita é lido adiante
            let p_next_op = p_loop.op;
            p_loop = match p_loop.p_prior.as_deref_mut() {
                Some(p_prior) => p_prior,
                None => break,
            };
            cnt += 1;
            if p_loop.p_order_by.is_some() || p_loop.p_limit.is_some() {
                let mut z_msg: Vec<u8> = Vec::new();
                z_msg.extend_from_slice(if p_loop.p_order_by.is_some() {
                    b"ORDER BY"
                } else {
                    b"LIMIT"
                });
                z_msg.extend_from_slice(b" clause should come after ");
                z_msg.extend_from_slice(select_op_name(p_next_op as i32));
                z_msg.extend_from_slice(b" not before");
                error_msg(p_parse, Some(&z_msg));
                break;
            }
        }
        if (p.sel_flags & (SF_MULTIVALUE | SF_VALUES)) == 0 {
            let db = p_parse.db.upgrade().expect("conexão de banco viva durante o parse");
            let mx_select = db.borrow().a_limit[SQLITE_LIMIT_COMPOUND_SELECT as usize];
            if mx_select > 0 && cnt > mx_select {
                error_msg(p_parse, Some(b"too many terms in compound SELECT"));
            }
        }
    }
}

/// Anexa um objeto With que descreve a cláusula WITH ao Select da consulta da qual a cláusula
/// WITH é prefixo.
pub fn attach_with_to_select(
    p_parse: &mut Parse,
    p_select: Option<Box<Select>>,
    p_with: Option<WithRef>,
) -> Option<Box<Select>> {
    let mut p_select = p_select;
    match p_select.as_deref_mut() {
        Some(select) => {
            select.p_with = p_with;
            parser_double_link_select(p_parse, select);
        }
        None => {
            let db = p_parse.db.upgrade().expect("conexão de banco viva durante o parse");
            with_delete(&db, p_with);
        }
    }
    p_select
}

/// Alocador para o redimensionamento da pilha do parser. É um invólucro fino de
/// `sqlite3_realloc()` que inclui uma chamada a `sqlite3FaultSim()` para facilitar os testes.
///
/// No Rust a pilha é um `Vec`: `None` é o ponteiro nulo do C (falha injetada, ou tamanho zero,
/// que em `sqlite3_realloc` libera o bloco e devolve nulo); o `Vec` devolvido tem exatamente
/// `new_size` bytes, com o conteúdo antigo preservado e o acréscimo zerado.
pub fn parser_stack_realloc(p_old: Vec<u8>, new_size: u64) -> Option<Vec<u8>> {
    if fault_sim(700) != 0 {
        return None;
    }
    // sqlite3_realloc() recebe um int: o sqlite3_uint64 é estreitado como no C.
    let n = new_size as i32;
    if n <= 0 {
        return None;
    }
    let mut p_new = p_old;
    p_new.resize(n as usize, 0);
    Some(p_new)
}

/// Constrói um novo objeto Expr a partir de um único token.
pub fn token_expr(p_parse: &mut Parse, op: i32, t: Token) -> Option<Box<Expr>> {
    // sqlite3DbMallocRawNN() devolveria nulo em falta de memória; a alocação do Box não falha,
    // então o ramo `if( p )` do C é sempre tomado.
    let z_token: Vec<u8> = t.z[..t.n as usize].to_vec();
    let quoted = z_token.first().map_or(false, |&c| isquote(c));
    let mut p = Box::new(Expr {
        op: op as u8,
        aff_expr: 0,
        op2: 0,
        flags: EP_LEAF,
        // ExprClearVVAProperties(p) só existe sob SQLITE_DEBUG e some.
        u: ExprU { z_token: Some(z_token), i_value: 0 },
        p_left: None,
        p_right: None,
        x: ExprX::default(),
        // SQLITE_MAX_EXPR_DEPTH>0
        n_height: 1,
        i_table: 0,
        i_column: 0,
        // p->iAgg = -1; não é necessário no C (campo não inicializado).
        i_agg: -1,
        // NOTA para o lead: `t.z - pParse->zTail` é diferença de ponteiros no C. O `Token` do
        // modelo Rust carrega cópia do texto e não a posição; assume-se aqui o campo
        // `Token.i_pos` (deslocamento absoluto de `z` no texto SQL, o equivalente do ponteiro),
        // a ser acrescentado ao tipo e preenchido pelo tokenizador.
        w: ExprW { i_join: 0, i_ofst: (t.i_pos as i64 - p_parse.z_tail as i64) as i32 },
        p_agg_info: None,
        y: ExprY::default(),
    });
    if quoted {
        dequote_expr(&mut p);
    }
    if in_rename_object(p_parse) {
        return Some(rename_token_map(p_parse, p, &t));
    }
    Some(p)
}

/// Converte uma expressão binária TK_IS ou TK_ISNOT na expressão unária TK_ISNULL ou TK_NOTNULL.
///
/// No C `pY` é o operando direito de `pA` (`pA->pRight`), que o Rust não deixa emprestar junto
/// com `pA`; o chamador passa em `p_y_op` o `op` de Y (ou `None` se Y é nulo), lido antes de Y
/// ser movido para dentro de `pA`.
pub fn binary_to_unary_if_null(
    p_parse: &mut Parse,
    p_y_op: Option<u8>,
    p_a: Option<&mut Expr>,
    op: i32,
) {
    let db = p_parse.db.upgrade().expect("conexão de banco viva durante o parse");
    if let Some(p_a) = p_a {
        if p_y_op == Some(TK_NULL) && !in_rename_object(p_parse) {
            p_a.op = op as u8;
            expr_delete(&db, p_a.p_right.take());
        }
    }
}

/// Acrescenta um único termo novo a uma ExprList que guarda uma lista de identificadores.
/// Informa erro se a lista de ID contém uma cláusula COLLATE ou a palavra-chave ASC ou DESC,
/// exceto durante a análise de um schema legado.
pub fn parser_add_expr_id_list_term(
    p_parse: &mut Parse,
    p_prior: Option<Box<ExprList>>,
    p_id_token: &Token,
    has_collate: i32,
    sort_order: i32,
) -> Option<Box<ExprList>> {
    let mut p = expr_list_append(p_parse, p_prior, None);
    let busy = p_parse
        .db
        .upgrade()
        .expect("conexão de banco viva durante o parse")
        .borrow()
        .init
        .busy;
    if (has_collate != 0 || sort_order != SQLITE_SO_UNDEFINED) && busy == 0 {
        // "%.*s" do C: no máximo `n` bytes, parando num nulo. O `error_msg` recebe o formato
        // já montado, então o '%' do identificador sai duplicado.
        let mut z_msg: Vec<u8> = Vec::new();
        z_msg.extend_from_slice(b"syntax error after column name \"");
        for &c in p_id_token.z[..p_id_token.n as usize].iter().take_while(|&&c| c != 0) {
            if c == b'%' {
                z_msg.push(b'%');
            }
            z_msg.push(c);
        }
        z_msg.push(b'"');
        error_msg(p_parse, Some(&z_msg));
    }
    expr_list_set_name(p_parse, p.as_deref_mut(), p_id_token, 1);
    p
}

// A verificação `#if TK_SPAN>255 / #error` do C vale em tempo de compilação: `TK_SPAN` é u8.

// Tipos de código dos símbolos e das ações (parâmetros de controle do lemon).

/// Tipo dos códigos inteiros dos símbolos terminais e não terminais.
pub type YYCODETYPE = u16;
/// Valor de YYCODETYPE que não é usado por nenhum símbolo.
pub const YYNOCODE: YYCODETYPE = 322;
/// Tipo dos códigos de ação.
pub type YYACTIONTYPE = u16;
/// Símbolo curinga (TK_ANY).
pub const YYWILDCARD: YYCODETYPE = 101;

/// Valor semântico (minor) de um símbolo na pilha do parser. No C é uma union (`YYMINORTYPE`) em
/// que cada gramática-símbolo usa um membro; o Rust seguro não tem union, então todos os membros
/// existem lado a lado e as ações da gramática leem e gravam só o membro que o C usaria (sempre
/// com `.take()` ou atribuição, nunca duas posses do mesmo objeto).
///
/// NOTA para o lead: `YyStackEntry` deriva `Clone`, o que exige `Clone` nos tipos de nó
/// (ExprList, Select, SrcList, IdList, TriggerStep, Window, Cte, Upsert, OnOrUsing, Expr) ou a
/// remoção do `derive(Clone)` da pilha.
#[derive(Clone, Default)]
pub struct YYMINORTYPE {
    pub yyinit: i32,
    /// Símbolos terminais (sqlite3ParserTOKENTYPE = Token).
    pub yy0: Token,
    pub yy14: Option<Box<ExprList>>,
    pub yy59: Option<WithRef>,
    pub yy67: Option<Box<Cte>>,
    pub yy122: Option<Box<Upsert>>,
    pub yy132: Option<Box<IdList>>,
    pub yy144: i32,
    /// `const char*`; `None` é o ponteiro nulo.
    pub yy168: Option<Vec<u8>>,
    pub yy203: Option<Box<SrcList>>,
    pub yy211: Option<Box<Window>>,
    pub yy269: OnOrUsing,
    pub yy286: TrigEvent,
    pub yy383: YyValueMask,
    pub yy391: u32,
    pub yy427: Option<Box<TriggerStep>>,
    pub yy454: Option<Box<Expr>>,
    pub yy462: u8,
    pub yy509: FrameBound,
    pub yy555: Option<Box<Select>>,
}

/// A `struct {int value; int mask;}` anônima do membro `yy383` de YYMINORTYPE.
#[derive(Clone, Copy, Default)]
pub struct YyValueMask {
    pub value: i32,
    pub mask: i32,
}


