// A tabela a seguir mapeia tokens (símbolos terminais) em tokens de fallback.
// Se a gramática contém `%fallback ID X Y Z.`, então ID vira o fallback de
// X, Y e Z: sempre que um destes tokens chega ao analisador mas não casa, o
// tipo do token muda para ID e a análise é repetida antes de lançar o erro.
// Serve, por exemplo, para que algumas palavras-chave voltem a ser
// identificadores quando não se aplicam no contexto em que aparecem.
