// ---- part_003.rs ----

// Trecho 3 de parse.c: as duas estruturas da pilha do parser gerado pelo lemon.
//
// Fora do porte, por não existirem no build do Debian (NDEBUG definido, sem YYCOVERAGE):
//   - `yyTraceFILE`, `yyTracePrompt` e `sqlite3ParserTrace()` (rastreio do parser);
//   - a tabela `yyTokenName[]` (nomes dos símbolos, usada só no rastreio).
// Também ficam de fora `yyerrcnt` (YYNOERRORRECOVERY é definido, então o campo não existe),
// `yyhwm` (YYTRACKMAXSTACKDEPTH não é definido) e o argumento extra do
// parser (`sqlite3ParserARG_SDECL` é vazio); o contexto `sqlite3ParserCTX_SDECL` é `Parse *pParse`.

/// Um elemento da pilha do parser. Guarda o número de estado deste nível da pilha, o valor do
/// token ("major") e o valor semântico usado pelas ações da gramática ("minor").
///
/// Depois da metade "shift" de uma ação SHIFTREDUCE, o campo `stateno` guarda na verdade a ação
/// de redução da segunda metade do SHIFTREDUCE.
#[derive(Clone, Default)]
pub struct YyStackEntry {
    /// O número de estado, ou a ação de redução em um SHIFTREDUCE.
    pub stateno: YYACTIONTYPE,
    /// O código do token neste nível da pilha.
    pub major: YYCODETYPE,
    /// O valor do token fornecido pelo usuário.
    pub minor: YYMINORTYPE,
}

/// O estado do parser inteiro. No C `yytos`, `yystackEnd` e `yystack` são ponteiros para
/// elementos da pilha; aqui `yytos` e `yystack_end` são índices em `yystack`. A pilha inicial
/// (`yystk0[YYSTACKDEPTH]`) e a pilha crescida na heap (YYDYNSTACK) se fundem num só `Vec`,
/// cujo tamanho inicial é `YYSTACKDEPTH` entradas.
pub struct YyParser {
    /// Índice do elemento do topo da pilha.
    pub yytos: usize,
    /// O contexto do parser (`sqlite3ParserCTX_SDECL`: `Parse *pParse`).
    pub p_parse: ParseRef,
    /// Índice da última entrada da pilha.
    pub yystack_end: usize,
    /// A pilha do parser.
    pub yystack: Vec<YyStackEntry>,
}


