// ---- part_005.rs ----

// Trecho 5 de parse.c: crescimento da pilha, inicialização, destrutores e a busca da ação de shift.
//
// Fora do porte, por não existirem no build do Debian:
//   - os blocos `#ifndef NDEBUG` (rastreio do parser: `yyTraceFILE`, `yyTracePrompt`);
//   - `sqlite3ParserAlloc()` e `sqlite3ParserFree()`, omitidos porque o amalgamation define
//     `sqlite3Parser_ENGINEALWAYSONSTACK` (o `YyParser` vive na pilha de quem chama);
//   - `sqlite3ParserStackPeak()` (`YYTRACKMAXSTACKDEPTH` não é definido);
//   - `yycoverage[][]` e `sqlite3ParserCoverage()` (`YYCOVERAGE` não é definido);
//   - `yyerrcnt` (`YYNOERRORRECOVERY` é definido, então `sqlite3ParserInit()` não o inicializa).
//
// `YYGROWABLESTACK` vale 1 (`YYDYNSTACK` é 1), então `yyGrowStack()` existe de verdade. A pilha
// inicial (`yystk0`) e a pilha crescida na heap se fundem num só `Vec`.

/// Tenta aumentar o tamanho da pilha do parser. Devolve o número de erros: 0 em caso de sucesso.
fn yy_grow_stack(p: &mut YyParser) -> i32 {
    let old_size: i32 = 1 + p.yystack_end as i32;
    let new_size: i32;
    let idx: usize;

    new_size = old_size * 2 + 100;
    idx = p.yytos;
    // `parserStackRealloc()`: `sqlite3FaultSim(700) ? 0 : sqlite3_realloc(...)`. O Vec preserva as
    // entradas existentes (o memcpy da pilha inicial e o realloc da pilha da heap).
    if fault_sim(700) != 0 {
        return 1;
    }
    p.yystack.resize(new_size as usize, YyStackEntry::default());
    p.yytos = idx;
    p.yystack_end = (new_size - 1) as usize;
    0
}

/// Inicializa um parser que já foi alocado.
pub fn parser_init(yyp_parser: &mut YyParser, p_parse: ParseRef) {
    yyp_parser.p_parse = p_parse;
    yyp_parser.yystack = vec![YyStackEntry::default(); YYSTACKDEPTH as usize];
    yyp_parser.yystack_end = (YYSTACKDEPTH - 1) as usize;
    yyp_parser.yytos = 0;
    yyp_parser.yystack[0].stateno = 0;
    yyp_parser.yystack[0].major = 0;
}

/// Apaga o "tipo menor", o valor semântico associado a um símbolo, terminal ou não terminal.
/// `yymajor` é o código do símbolo e `yypminor` é o valor a destruir. O código usado para as
/// destruições vem das diretivas `%destructor` e/ou `%token_destructor` da gramática.
fn yy_destructor(yy_parser: &YyParser, yymajor: YYCODETYPE, yypminor: &mut YYMINORTYPE) {
    // sqlite3ParserCTX_FETCH: `Parse *pParse = yypParser->pParse;` (só `pParse->db` é usado)
    let db = match yy_parser.p_parse.borrow().db.upgrade() {
        Some(db) => db,
        None => return,
    };
    match yymajor as i32 {
        // Aqui entram as ações que acontecem quando um terminal ou não terminal é destruído. Isso
        // pode acontecer quando o símbolo sai da pilha durante uma redução ou durante o
        // tratamento de erro, ou quando o parser é destruído antes de terminar.
        //
        // Nota: durante uma redução, os únicos símbolos destruídos são os do lado direito da
        // regra que *não* são usados dentro do código C.
        205 /* select */
        | 240 /* selectnowith */
        | 241 /* oneselect */
        | 253 /* values */
        | 255 /* mvalues */ => {
            select_delete(&db, yypminor.yy555.take());
        }
        217 /* term */
        | 218 /* expr */
        | 247 /* where_opt */
        | 249 /* having_opt */
        | 269 /* where_opt_ret */
        | 280 /* case_operand */
        | 282 /* case_else */
        | 285 /* vinto */
        | 292 /* when_clause */
        | 297 /* key_opt */
        | 314 /* filter_clause */ => {
            expr_delete(&db, yypminor.yy454.take());
        }
        222 /* eidlist_opt */
        | 232 /* sortlist */
        | 233 /* eidlist */
        | 245 /* selcollist */
        | 248 /* groupby_opt */
        | 250 /* orderby_opt */
        | 254 /* nexprlist */
        | 256 /* sclp */
        | 263 /* exprlist */
        | 270 /* setlist */
        | 279 /* paren_exprlist */
        | 281 /* case_exprlist */
        | 313 /* part_opt */ => {
            expr_list_delete(&db, yypminor.yy14.take());
        }
        239 /* fullname */
        | 246 /* from */
        | 258 /* seltablist */
        | 259 /* stl_prefix */
        | 264 /* xfullname */ => {
            src_list_delete(&db, yypminor.yy203.take());
        }
        242 /* wqlist */ => {
            with_delete(&db, yypminor.yy59.take());
        }
        252 /* window_clause */
        | 309 /* windowdefn_list */ => {
            window_list_delete(&db, yypminor.yy211.take());
        }
        265 /* idlist */
        | 272 /* idlist_opt */ => {
            id_list_delete(&db, yypminor.yy132.take());
        }
        275 /* filter_over */
        | 310 /* windowdefn */
        | 311 /* window */
        | 312 /* frame_opt */
        | 315 /* over_clause */ => {
            window_delete(&db, yypminor.yy211.take());
        }
        288 /* trigger_cmd_list */
        | 293 /* trigger_cmd */ => {
            delete_trigger_step(&db, yypminor.yy427.take());
        }
        290 /* trigger_event */ => {
            id_list_delete(&db, yypminor.yy286.b.take());
        }
        317 /* frame_bound */
        | 318 /* frame_bound_s */
        | 319 /* frame_bound_e */ => {
            expr_delete(&db, yypminor.yy509.p_expr.take());
        }
        _ => {} // Se não há ação de destrutor especificada: não faz nada
    }
}

/// Desempilha uma vez a pilha do parser. Se há uma rotina destrutora associada ao token que
/// saiu da pilha, ela é chamada.
fn yy_pop_parser_stack(p_parser: &mut YyParser) {
    debug_assert!(p_parser.yytos > 0);
    let yytos = p_parser.yytos;
    p_parser.yytos -= 1;
    let major = p_parser.yystack[yytos].major;
    let mut minor = std::mem::take(&mut p_parser.yystack[yytos].minor);
    yy_destructor(p_parser, major, &mut minor);
}

/// Limpa todas as alocações secundárias do parser.
pub fn parser_finalize(p_parser: &mut YyParser) {
    // Versão inline de chamar yy_pop_parser_stack() para cada elemento que sobrou na pilha
    let mut yytos = p_parser.yytos;
    while yytos > 0 {
        if p_parser.yystack[yytos].major as i32 >= YY_MIN_DSTRCTR {
            let major = p_parser.yystack[yytos].major;
            let mut minor = std::mem::take(&mut p_parser.yystack[yytos].minor);
            yy_destructor(p_parser, major, &mut minor);
        }
        yytos -= 1;
    }

    // `if( pParser->yystack!=pParser->yystk0 ) YYFREE(pParser->yystack);`: o Vec é liberado no drop
}

/// Acha a ação apropriada para o parser dado o token terminal de lookahead `i_look_ahead`.
fn yy_find_shift_action(mut i_look_ahead: YYCODETYPE, stateno: YYACTIONTYPE) -> YYACTIONTYPE {
    let mut i: i32;

    if stateno as i32 > YY_MAX_SHIFT {
        return stateno;
    }
    debug_assert!(stateno as i32 <= YY_SHIFT_COUNT);
    loop {
        i = YY_SHIFT_OFST[stateno as usize] as i32;
        debug_assert!(i >= 0);
        debug_assert!(i <= YY_ACTTAB_COUNT);
        debug_assert!(i + YYNTOKEN <= YY_NLOOKAHEAD);
        debug_assert!(i_look_ahead as i32 != YYNOCODE as i32);
        debug_assert!((i_look_ahead as i32) < YYNTOKEN);
        i += i_look_ahead as i32;
        debug_assert!(i < YY_NLOOKAHEAD);
        if YY_LOOKAHEAD[i as usize] as i32 != i_look_ahead as i32 {
            // YYFALLBACK
            debug_assert!((i_look_ahead as usize) < YY_FALLBACK.len());
            let i_fallback = YY_FALLBACK[i_look_ahead as usize]; // Token de fallback
            if i_fallback != 0 {
                debug_assert!(YY_FALLBACK[i_fallback as usize] == 0); // O laço de fallback precisa terminar
                i_look_ahead = i_fallback as YYCODETYPE;
                continue;
            }
            // YYWILDCARD
            {
                let j: i32 = i - i_look_ahead as i32 + YYWILDCARD as i32;
                debug_assert!((j as usize) < YY_LOOKAHEAD.len());
                if YY_LOOKAHEAD[j as usize] as i32 == YYWILDCARD as i32 && i_look_ahead as i32 > 0 {
                    return YY_ACTION[j as usize] as YYACTIONTYPE;
                }
            }
            return YY_DEFAULT[stateno as usize] as YYACTIONTYPE;
        } else {
            debug_assert!(i >= 0 && (i as usize) < YY_ACTION.len());
            return YY_ACTION[i as usize] as YYACTIONTYPE;
        }
    }
}


// ---- part_006.rs ----

// Trecho 6 de parse.c: busca da ação de redução, estouro da pilha, a ação shift e a tabela
// com o símbolo do lado esquerdo de cada regra da gramática (gerado pelo lemon).
//
// Fora do porte, por não existirem no build do Debian (NDEBUG definido):
//   - `yyTraceShift()` (rastreio da ação SHIFT, vira nada);
//   - o ramo `YYERRORSYMBOL` de `yy_find_reduce_action` (a gramática do SQLite não define o
//     símbolo de erro), ficando só o ramo sem ele.
// `sqlite3ParserARG_FETCH` e `sqlite3ParserARG_STORE` são vazios; o contexto
// (`sqlite3ParserCTX_FETCH`) é o `Parse` guardado em `YyParser::p_parse`.

/// Encontra a ação apropriada para o parser dado o não terminal de lookahead `i_look_ahead`.
pub fn yy_find_reduce_action(stateno: YYACTIONTYPE, i_look_ahead: YYCODETYPE) -> YYACTIONTYPE {
    debug_assert!((stateno as i32) <= YY_REDUCE_COUNT);
    let mut i: i32 = YY_REDUCE_OFST[stateno as usize] as i32;
    debug_assert!(i_look_ahead as i32 != YYNOCODE as i32);
    i += i_look_ahead as i32;
    debug_assert!(i >= 0 && i < YY_ACTTAB_COUNT as i32);
    debug_assert!(YY_LOOKAHEAD[i as usize] as i32 == i_look_ahead as i32);
    YY_ACTION[i as usize]
}

/// Chamada quando a pilha estoura.
pub fn yy_stack_overflow(yyp_parser: &mut YyParser) {
    let p_parse = yyp_parser.p_parse.clone();
    while yyp_parser.yytos > 0 {
        yy_pop_parser_stack(yyp_parser);
    }
    // Aqui entra o código que executa se a pilha do parser algum dia estourar
    // (`%stack_overflow`).
    let db = p_parse.borrow().db.upgrade();
    if let Some(db) = db {
        oom_fault(&mut db.borrow_mut());
    }
}

/// Executa uma ação shift.
pub fn yy_shift(
    yyp_parser: &mut YyParser,
    yy_new_state: YYACTIONTYPE,
    yy_major: YYCODETYPE,
    yy_minor: Token,
) {
    let mut yy_new_state = yy_new_state;
    yyp_parser.yytos += 1;
    if yyp_parser.yytos > yyp_parser.yystack_end {
        if yy_grow_stack(yyp_parser) != 0 {
            yyp_parser.yytos -= 1;
            yy_stack_overflow(yyp_parser);
            return;
        }
        debug_assert!(yyp_parser.yytos <= yyp_parser.yystack_end);
    }
    let yytos = yyp_parser.yytos;
    if (yy_new_state as i32) > YY_MAX_SHIFT as i32 {
        yy_new_state = (yy_new_state as i32 + (YY_MIN_REDUCE as i32 - YY_MIN_SHIFTREDUCE as i32))
            as YYACTIONTYPE;
    }
    let entry = &mut yyp_parser.yystack[yytos];
    entry.stateno = yy_new_state;
    entry.major = yy_major;
    entry.minor.yy0 = yy_minor;
}

