// ---- part_012.rs ----

// Trecho 12 de parse.c (gerado pelo lemon a partir de parse.y): o fim da função `yy_reduce`
// (casos 323 a 343 e o ramo default), as rotinas de falha, de erro de sintaxe e de aceitação, e o
// laço principal do parser, `sqlite3Parser`.
//
// NOTA para o lead (costura do `yy_reduce`): o corpo do `switch (yyruleno)` do C atravessa os
// trechos 8 a 12, e um item Rust não pode ser dividido entre arquivos. Este trecho entrega:
//   - `yy_reduce_case_323_tail`: as duas linhas finais do `case 323`, que começa no trecho 11
//     (a atribuição `yymsp[-5].minor.yy211 = yylhsminor.yy211;` e o `break`);
//   - `yy_reduce_cases_325_to_343`: os casos 325 a 343 e o ramo `default`;
//   - `yy_reduce_finish`: o código que vem depois do `switch` (busca da ação goto, ajuste do
//     topo da pilha e retorno da ação).
// O `yy_reduce` montado no `mod.rs` chama, no `match yyruleno`, `yy_reduce_case_323_tail` ao fim do
// caso 323, entrega os casos 325..=343 e o default a `yy_reduce_cases_325_to_343` (passando o
// mesmo `yylhsminor` das demais ações) e termina com `yy_reduce_finish`. `yymsp` é o índice de
// `yy_parser.yystack` que no C é o ponteiro `yymsp`.
//
// Fora do porte, por não existirem no build do Debian (NDEBUG definido, sem YYERRORSYMBOL, sem
// YYTRACKMAXSTACKDEPTH):
//   - todo o rastreio (`yyTraceFILE`, `yyTraceShift`, as mensagens "Input ...", "Reduce ...",
//     "Return. Stack=" e afins);
//   - o ramo `YYERRORSYMBOL` do tratamento de erro do `sqlite3Parser` e o ramo
//     `YYNOERRORRECOVERY`; fica só o ramo "gramática sem símbolo de erro";
//   - as macros `yytestcase` (cobertura de teste) e `sqlite3ParserARG_*` (vazias).

/// Fim do `case 323` (`frame_opt ::= range_or_rows BETWEEN frame_bound_s AND frame_bound_e
/// frame_exclude_opt`): o corpo `{ ... }` começa no trecho 11 e deixa o resultado em
/// `yylhsminor.yy211`; aqui ele é gravado na posição `yymsp[-5]`.
pub fn yy_reduce_case_323_tail(
    yy_parser: &mut YyParser,
    yymsp: usize,
    yylhsminor: &mut YYMINORTYPE,
) {
    yy_parser.yystack[yymsp - 5].minor.yy211 = yylhsminor.yy211.take();
}

/// Casos 325 a 343 das ações de redução da gramática, mais o ramo `default`. `yylhsminor` é o
/// `YYMINORTYPE yylhsminor` declarado no início do `switch` do C, compartilhado pelos casos.
pub fn yy_reduce_cases_325_to_343(
    yy_parser: &mut YyParser,
    yyruleno: u32,
    yymsp: usize,
    yylhsminor: &mut YYMINORTYPE,
) {
    // sqlite3ParserCTX_FETCH: o `Parse *pParse` da pilha do parser.
    let p_parse = yy_parser.p_parse.clone();
    let stk = &mut yy_parser.yystack;
    match yyruleno {
        325 /* frame_bound_s ::= frame_bound */
        | 327 /* frame_bound_e ::= frame_bound */ => {
            yylhsminor.yy509 = std::mem::take(&mut stk[yymsp].minor.yy509);
            stk[yymsp].minor.yy509 = std::mem::take(&mut yylhsminor.yy509);
        }
        326 /* frame_bound_s ::= UNBOUNDED PRECEDING */
        | 328 /* frame_bound_e ::= UNBOUNDED FOLLOWING */
        | 330 /* frame_bound ::= CURRENT ROW */ => {
            yylhsminor.yy509.e_type = stk[yymsp - 1].major as i32;
            yylhsminor.yy509.p_expr = None;
            stk[yymsp - 1].minor.yy509 = std::mem::take(&mut yylhsminor.yy509);
        }
        329 /* frame_bound ::= expr PRECEDING|FOLLOWING */ => {
            yylhsminor.yy509.e_type = stk[yymsp].major as i32;
            yylhsminor.yy509.p_expr = stk[yymsp - 1].minor.yy454.take();
            stk[yymsp - 1].minor.yy509 = std::mem::take(&mut yylhsminor.yy509);
        }
        331 /* frame_exclude_opt ::= */ => {
            stk[yymsp + 1].minor.yy462 = 0;
        }
        332 /* frame_exclude_opt ::= EXCLUDE frame_exclude */ => {
            stk[yymsp - 1].minor.yy462 = stk[yymsp].minor.yy462;
        }
        333 /* frame_exclude ::= NO OTHERS */
        | 334 /* frame_exclude ::= CURRENT ROW */ => {
            // A-overwrites-X
            stk[yymsp - 1].minor.yy462 = stk[yymsp - 1].major as u8;
        }
        335 /* frame_exclude ::= GROUP|TIES */ => {
            // A-overwrites-X
            stk[yymsp].minor.yy462 = stk[yymsp].major as u8;
        }
        336 /* window_clause ::= WINDOW windowdefn_list */ => {
            stk[yymsp - 1].minor.yy211 = stk[yymsp].minor.yy211.take();
        }
        337 /* filter_over ::= filter_clause over_clause */ => {
            let p_filter = stk[yymsp - 1].minor.yy454.take();
            match stk[yymsp].minor.yy211.as_deref_mut() {
                Some(p_win) => {
                    p_win.p_filter = p_filter;
                }
                None => {
                    let db = p_parse
                        .borrow()
                        .db
                        .upgrade()
                        .expect("conexão de banco viva durante o parse");
                    expr_delete(&db, p_filter);
                }
            }
            yylhsminor.yy211 = stk[yymsp].minor.yy211.take();
            stk[yymsp - 1].minor.yy211 = yylhsminor.yy211.take();
        }
        338 /* filter_over ::= over_clause */ => {
            yylhsminor.yy211 = stk[yymsp].minor.yy211.take();
            stk[yymsp].minor.yy211 = yylhsminor.yy211.take();
        }
        339 /* filter_over ::= filter_clause */ => {
            // sqlite3DbMallocZero(pParse->db, sizeof(Window)): o Box não falha, então o ramo
            // `else` (falta de memória, que liberava a expressão) nunca é tomado.
            let mut p_win = Box::new(Window::default());
            p_win.e_frm_type = TK_FILTER as u8;
            p_win.p_filter = stk[yymsp].minor.yy454.take();
            yylhsminor.yy211 = Some(p_win);
            stk[yymsp].minor.yy211 = yylhsminor.yy211.take();
        }
        340 /* over_clause ::= OVER LP window RP */ => {
            stk[yymsp - 3].minor.yy211 = stk[yymsp - 1].minor.yy211.take();
            debug_assert!(stk[yymsp - 3].minor.yy211.is_some());
        }
        341 /* over_clause ::= OVER nm */ => {
            let mut p_win = Box::new(Window::default());
            let db = p_parse
                .borrow()
                .db
                .upgrade()
                .expect("conexão de banco viva durante o parse");
            let tok = &stk[yymsp].minor.yy0;
            let z_name = db_str_n_dup(&mut db.borrow_mut(), Some(&tok.z[..tok.n as usize]), tok.n as u64);
            p_win.z_name = Some(z_name);
            stk[yymsp - 1].minor.yy211 = Some(p_win);
        }
        342 /* filter_clause ::= FILTER LP WHERE expr RP */ => {
            stk[yymsp - 4].minor.yy454 = stk[yymsp - 1].minor.yy454.take();
        }
        343 /* term ::= QNUMBER */ => {
            let major = stk[yymsp].major as i32;
            let t = stk[yymsp].minor.yy0.clone();
            yylhsminor.yy454 = token_expr(&mut p_parse.borrow_mut(), major, t);
            dequote_number(Some(&mut p_parse.borrow_mut()), yylhsminor.yy454.as_deref_mut());
            stk[yymsp].minor.yy454 = yylhsminor.yy454.take();
        }
        _ => {
            // (344) input ::= cmdlist, (345) cmdlist ::= cmdlist ecmd, (347) ecmd ::= SEMI,
            // (348) ecmd ::= cmdx SEMI, (350) a (354) trans_opt e savepoint_opt, (355) cmd ::=
            // create_table create_table_args, (357) e (358) columnlist, (359) a (362) nm e
            // typename, (365) a (371), (373), (377), (378), (379), (381), (383), (384), (385),
            // (388) a (406): regras sem ação própria, nada a fazer.
            //
            // As regras abaixo foram otimizadas fora (OPTIMIZED OUT) ou nunca reduzem.
            debug_assert!(
                !matches!(
                    yyruleno,
                    346 | 349
                        | 356
                        | 363
                        | 364
                        | 372
                        | 374
                        | 375
                        | 376
                        | 380
                        | 382
                        | 386
                        | 387
                        | 407
                        | 408
                )
            );
        }
    }
}

/// O que o `yy_reduce` do C faz depois do `switch`: acha a ação goto do símbolo do lado esquerdo
/// da regra, ajusta o topo da pilha e devolve a ação.
pub fn yy_reduce_finish(yy_parser: &mut YyParser, yyruleno: u32, yymsp: usize) -> YYACTIONTYPE {
    debug_assert!((yyruleno as usize) < YY_RULE_INFO_LHS.len());
    let yygoto: YYCODETYPE = YY_RULE_INFO_LHS[yyruleno as usize];
    let yysize: i32 = YY_RULE_INFO_N_RHS[yyruleno as usize] as i32;
    let base = (yymsp as i64 + yysize as i64) as usize;
    let yyact: YYACTIONTYPE = yy_find_reduce_action(yy_parser.yystack[base].stateno, yygoto);

    // Não há ações SHIFTREDUCE em não terminais, porque o gerador de tabelas as simplificou
    // para REDUCE puro.
    debug_assert!(!((yyact as i32) > YY_MAX_SHIFT && (yyact as i32) <= YY_MAX_SHIFTREDUCE));

    // Uma redução nunca é seguida de erro.
    debug_assert!(yyact as i32 != YY_ERROR_ACTION);

    let yymsp = base + 1;
    yy_parser.yytos = yymsp;
    yy_parser.yystack[yymsp].stateno = yyact;
    yy_parser.yystack[yymsp].major = yygoto;
    yyact
}

/// Executa quando o parse falha.
pub fn yy_parse_failed(yy_parser: &mut YyParser) {
    while yy_parser.yytos > 0 {
        yy_pop_parser_stack(yy_parser);
    }
    // Aqui entraria o código executado quando o parser falha (`%parse_failure`): não há nenhum.
}

/// Executa quando um erro de sintaxe ocorre pela primeira vez. `yymajor` é o tipo maior do token
/// do erro e `yyminor` é o próprio token.
pub fn yy_syntax_error(yy_parser: &mut YyParser, yymajor: i32, yyminor: Token) {
    let _ = yymajor; // UNUSED_PARAMETER(yymajor)
    let p_parse = yy_parser.p_parse.clone();
    // `TOKEN.z[0]` no C lê o primeiro byte do texto do token; no fim da entrada ele é o NUL.
    if matches!(yyminor.z.first(), Some(&c) if c != 0) {
        // O formato do C é `near "%T": syntax error`, e `%T` anexa os `n` bytes do token. Como
        // `error_msg` recebe o formato já pronto, o texto do token entra com `%` dobrado para o
        // formatador devolver os bytes literais.
        let n = std::cmp::min(yyminor.n as usize, yyminor.z.len());
        let mut z_msg: Vec<u8> = Vec::with_capacity(n + 24);
        z_msg.extend_from_slice(b"near \"");
        for &c in &yyminor.z[..n] {
            if c == b'%' {
                z_msg.push(b'%');
            }
            z_msg.push(c);
        }
        z_msg.extend_from_slice(b"\": syntax error");
        error_msg(&mut p_parse.borrow_mut(), Some(&z_msg));
    } else {
        error_msg(&mut p_parse.borrow_mut(), Some(b"incomplete input"));
    }
}

/// Executa quando o parser aceita a entrada.
pub fn yy_accept(yy_parser: &mut YyParser) {
    yy_parser.yyerrcnt = -1;
    debug_assert!(yy_parser.yytos == 0);
    // Aqui entraria o código executado quando o parser aceita (`%parse_accept`): não há nenhum.
}

/// O programa principal do parser (`sqlite3Parser`). `yy_parser` é a estrutura obtida de
/// `parser_alloc`, que descreve o estado atual do parser, `yymajor` é o código maior do token e
/// `yyminor` é o valor do token. O `Parse` do argumento extra (`sqlite3ParserARG_PDECL`, vazio) e
/// do contexto fica em `yy_parser.p_parse`.
pub fn parser(yy_parser: &mut YyParser, yymajor: i32, yyminor: Token) {
    let mut yyminorunion = YYMINORTYPE::default();
    let yyendofinput: bool; // Verdadeiro se estamos no fim da entrada

    debug_assert!(yy_parser.yytos < yy_parser.yystack.len());
    yyendofinput = yymajor == 0;

    let mut yyact: YYACTIONTYPE = yy_parser.yystack[yy_parser.yytos].stateno; // A ação do parser

    loop {
        // Sai por "break"
        debug_assert!(yy_parser.yytos < yy_parser.yystack.len());
        debug_assert!(yyact == yy_parser.yystack[yy_parser.yytos].stateno);
        yyact = yy_find_shift_action(yymajor as YYCODETYPE, yyact);
        if (yyact as i32) >= YY_MIN_REDUCE {
            let yyruleno: u32 = (yyact as i32 - YY_MIN_REDUCE) as u32; // Reduz por esta regra
            debug_assert!((yyruleno as i32) < YYNRULE);

            // Confere se a pilha tem espaço para crescer uma entrada se o lado direito da regra
            // é vazio. Isso garante espaço para empilhar o valor do lado esquerdo.
            if YY_RULE_INFO_N_RHS[yyruleno as usize] == 0 {
                if yy_parser.yytos >= yy_parser.yystack_end {
                    if yy_grow_stack(yy_parser) != 0 {
                        yy_stack_overflow(yy_parser);
                        break;
                    }
                }
            }
            yyact = yy_reduce(yy_parser, yyruleno, yymajor, yyminor.clone());
        } else if (yyact as i32) <= YY_MAX_SHIFTREDUCE {
            yy_shift(yy_parser, yyact, yymajor as YYCODETYPE, yyminor);
            yy_parser.yyerrcnt -= 1;
            break;
        } else if yyact as i32 == YY_ACCEPT_ACTION {
            yy_parser.yytos -= 1;
            yy_accept(yy_parser);
            return;
        } else {
            debug_assert!(yyact as i32 == YY_ERROR_ACTION);
            yyminorunion.yy0 = yyminor.clone();
            // Isto é o que fazemos se a gramática não define ERROR:
            //
            //  * Informa uma mensagem de erro e descarta o token de entrada.
            //
            //  * Se o token de entrada é $, o parse falha.
            //
            // Como antes, as mensagens de erro seguintes ficam suprimidas até três tokens serem
            // empilhados com sucesso.
            if yy_parser.yyerrcnt <= 0 {
                yy_syntax_error(yy_parser, yymajor, yyminor.clone());
            }
            yy_parser.yyerrcnt = 3;
            yy_destructor(yy_parser, yymajor as YYCODETYPE, &mut yyminorunion);
            if yyendofinput {
                yy_parse_failed(yy_parser);
                yy_parser.yyerrcnt = -1;
            }
            break;
        }
    }
    return;
}


// ---- part_013.rs ----

/// Devolve o token de fallback correspondente ao token canônico `i_token`,
/// ou 0 se `i_token` não tem fallback. YYFALLBACK está definido no Debian 13.
pub fn parser_fallback(i_token: i32) -> i32 {
    debug_assert!((i_token as usize) < YY_FALLBACK.len());
    YY_FALLBACK[i_token as usize] as i32
}

